programs.haiku:
"""Layer 15 MLP down_proj, component 3938: a diffuse response that goes negative at
punctuation and line breaks, and is near zero on ordinary words.

What it does, in plain terms:
- Line breaks are the strongest and most variable part. A line break right after a comma
  (a line of verse or lyrics ending in ',') is strongly negative, a break after a full stop
  is mildly negative, and a blank line after a space is more negative than a plain break.
- Chinese or Japanese text makes fullwidth commas and full stops, and commas, more negative.
- Comment markers in code ('//', '#') are negative.
- Indentation runs and tab-led breaks are slightly positive.
- Ordinary words and digits are about zero.

The program gives each kind of token the mean activation fitted on sample text. It is
a readable summary, not the full story: most of the variance sits in scattered
context-dependent values that no short rule captures.
"""

READS = ()

CJK_RANGES = ((0x3040, 0x30FF), (0x4E00, 0x9FFF))
FULLWIDTH_BOUNDARY = set("，、。！？：")
COMMENT_MARKERS = {"//", " //", "///", " ///", "#", " #"}
SENTENCE_STARTS = {" The", " And", " They", " If", " You", " We", " It", " This", " He", " She", " I"}


def is_cjk(ch):
    return any(lo <= ord(ch) <= hi for lo, hi in CJK_RANGES)


def in_cjk_text(recent):
    """True when at least three of the last twelve characters are Chinese or Japanese."""
    return sum(is_cjk(ch) for s in recent for ch in s) >= 3


def line_break_value(tok, cjk):
    """A token holding a line break, valued by the text just before it."""
    if tok.startswith("\t"):
        return 0.5  # tab-led line breaks in code
    before = tok.split("\n")[0]  # the text before the break, possibly spaces
    blank = tok.count("\n") > 1
    last = before[-1:]
    if last == ",":
        return -1.4 if blank else -2.4  # verse or lyrics line ending in a comma
    if last in FULLWIDTH_BOUNDARY:
        return -1.8
    if last == ".":
        return -0.25 if blank else -0.7
    if before == " ":
        return -1.8 if blank else -0.3  # a space then a blank line
    if before == "":
        return -0.25 if blank else -0.6  # a bare line break
    return -0.5 if cjk else -0.15


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    cjk = in_cjk_text(prefix.token_strings[-13:-1])
    if "\n" in tok:
        value = line_break_value(tok, cjk)
    elif tok.strip() == "":
        value = 0.15 if len(tok) > 1 else 0.0  # indentation runs
    elif tok in COMMENT_MARKERS:
        value = -3.0
    elif tok in FULLWIDTH_BOUNDARY:
        value = -2.2
    elif tok == ",":
        value = -2.2 if cjk else -0.1
    elif tok == ".":
        value = -0.4
    elif tok in SENTENCE_STARTS:
        value = -0.65
    elif tok in (":", ";"):
        value = -0.3
    else:
        value = 0.0
    return carry, value

"""Layer 15, MLP hidden unit 3949: the component's activation, as a short rule.

The component is essentially one MLP hidden unit (its input direction is almost
entirely unit 3949). Its clearest behaviour: it goes negative inside a clause
opened by the word "what" in the middle of a sentence, where "what" means
"the thing that" ("in what is now", "over what he called", "what appears to be").
- on "what" itself, most strongly after a preposition ("in what", "for what");
- on the subject or auxiliary right after it ("what is", "what he", "what's");
- more weakly on the next word or two, fading out by the third word after "what".
Everywhere else it is near zero with noise that this program does not model.
Sentence-initial "What" (a direct question) is only weakly negative.
"""

READS = ()

PREPOSITIONS = {
    "for", "over", "in", "with", "that", "from", "at", "of", "to", "like",
    "about", "by", "on", "out", "and", "or",
}
SUBJECT_OR_AUX = {
    "he", "she", "i", "we", "they", "you", "it", "is", "was", "are", "were",
    "be", "been", "am", "has", "have", "had", "would", "will", "can", "could",
    "may", "might", "must", "should", "do", "does", "did", "'s", "’s",
}


def step(carry, prefix, upstream):
    words = [s.strip().lower() for s in prefix.token_strings]
    docs = prefix.document_ids
    t = len(words) - 1

    def what_back(k):
        """Whether the token k positions back is 'what' in the same document."""
        i = t - k
        return i >= 0 and docs[i] == docs[t] and words[i] == "what"

    if words[t] == "what":
        prev_is_prep = t > 0 and docs[t - 1] == docs[t] and words[t - 1] in PREPOSITIONS
        if prev_is_prep:
            return carry, -6.5
        if prefix.token_strings[t].strip() == "What":
            return carry, -1.5
        return carry, -2.5
    if what_back(1):
        return carry, -5.5 if words[t] in SUBJECT_OR_AUX else -1.9
    if what_back(2):
        return carry, -1.9
    if what_back(3):
        return carry, -0.8
    return carry, 0.0
